using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    private const int CeilingPoints = 10;

    public int For(LoyaltyTier tier, int subtotalCents)
    {
        var basePoints = tier switch
        {
            LoyaltyTier.Bronze => 5,
            LoyaltyTier.Silver => 7,
            LoyaltyTier.Gold => 9,
        };
        var bonusPoints = subtotalCents switch
        {
            < 5000 => 0,
            < 20000 => 1,
            _ => 3,
        };
        var effectivePoints = Math.Min(basePoints + bonusPoints, CeilingPoints);
        var discountCents = subtotalCents * effectivePoints / 100;

        return subtotalCents - discountCents;
    }
}
